@page "/dispatcher"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@attribute [Authorize(Roles = "Dispatcher")]
@inject HttpClient Http

<PageTitle>Dispatcher Dashboard</PageTitle>

<h1>Shipment Dashboard</h1>

<div class="mb-3 d-flex gap-2 align-items-center">
    <input type="text" class="form-control" style="max-width: 300px;"
           placeholder="Filter by destination..."
           @bind="filterText" @bind:event="oninput" />
    <select class="form-select" style="max-width: 200px;" @bind="statusFilter">
        <option value="">All Statuses</option>
        @foreach (var status in Enum.GetValues<ShipmentStatus>())
        {
            <option value="@status">@status</option>
        }
    </select>
    <button class="btn btn-primary" @onclick="ShowCreateForm">
        + New Shipment
    </button>
</div>

@if (showCreateForm)
{
    <div class="card mb-3">
        <div class="card-body">
            <h5 class="card-title">Create New Shipment</h5>
            <EditForm Model="newShipment" OnValidSubmit="CreateShipment" FormName="createShipment">
                <div class="row g-2">
                    <div class="col-md-4">
                        <label class="form-label">Origin</label>
                        <InputText class="form-control" @bind-Value="newShipment.Origin" />
                    </div>
                    <div class="col-md-4">
                        <label class="form-label">Destination</label>
                        <InputText class="form-control" @bind-Value="newShipment.Destination" />
                    </div>
                    <div class="col-md-4">
                        <label class="form-label">Estimated Delivery</label>
                        <InputDate class="form-control" @bind-Value="newShipment.EstimatedDelivery" />
                    </div>
                    <div class="col-md-4">
                        <label class="form-label">Customer Email</label>
                        <InputText class="form-control" @bind-Value="newShipment.CustomerEmail" />
                    </div>
                    <div class="col-md-4">
                        <label class="form-label">Recipient Name</label>
                        <InputText class="form-control" @bind-Value="newShipment.RecipientName" />
                    </div>
                    <div class="col-md-4">
                        <label class="form-label">Description</label>
                        <InputText class="form-control" @bind-Value="newShipment.Description" />
                    </div>
                </div>
                <div class="mt-2">
                    <button type="submit" class="btn btn-success">Create</button>
                    <button type="button" class="btn btn-secondary" @onclick="() => showCreateForm = false">Cancel</button>
                </div>
            </EditForm>
        </div>
    </div>
}

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else if (!FilteredShipments.Any())
{
    <p>No shipments match your filter.</p>
}
else
{
    <table class="table table-striped table-hover">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Customer</th>
                <th>Est. Delivery</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in FilteredShipments)
            {
                <tr>
                    <td><code>@shipment.TrackingNumber</code></td>
                    <td>@shipment.Origin</td>
                    <td>@shipment.Destination</td>
                    <td>
                        <span class="badge @GetStatusBadgeClass(shipment.Status)">
                            @shipment.Status
                        </span>
                    </td>
                    <td>@shipment.RecipientName</td>
                    <td>@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                    <td>
                        <select class="form-select form-select-sm" style="width: auto;"
                                value="@shipment.Status"
                                @onchange="(e) => UpdateStatus(shipment, e)">
                            @foreach (var status in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@status" selected="@(shipment.Status == status)">@status</option>
                            }
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<ShipmentDto>? shipments;
    private string filterText = "";
    private string statusFilter = "";
    private bool showCreateForm;
    private CreateShipmentModel newShipment = new();

    private IEnumerable<ShipmentDto> FilteredShipments =>
        shipments?.Where(s =>
            (string.IsNullOrEmpty(filterText) || s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)) &&
            (string.IsNullOrEmpty(statusFilter) || s.Status.ToString() == statusFilter)
        ) ?? [];

    protected override async Task OnInitializedAsync()
    {
        shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("/api/shipments");
    }

    private void ShowCreateForm()
    {
        newShipment = new() { EstimatedDelivery = DateTime.UtcNow.AddDays(5) };
        showCreateForm = true;
    }

    private async Task CreateShipment()
    {
        var response = await Http.PostAsJsonAsync("/api/shipments", new
        {
            newShipment.Origin,
            newShipment.Destination,
            newShipment.EstimatedDelivery,
            newShipment.CustomerEmail,
            newShipment.RecipientName,
            newShipment.Description
        });

        if (response.IsSuccessStatusCode)
        {
            var created = await response.Content.ReadFromJsonAsync<ShipmentDto>();
            shipments?.Insert(0, created!);
            showCreateForm = false;
        }
    }

    private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            var response = await Http.PutAsJsonAsync($"/api/shipments/{shipment.Id}/status", new { Status = newStatus });
            if (response.IsSuccessStatusCode)
            {
                shipment.Status = newStatus;
                if (newStatus == ShipmentStatus.Delivered)
                    shipment.ActualDelivery = DateTime.UtcNow;
            }
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Exception => "bg-danger",
        _ => "bg-secondary"
    };

    private class CreateShipmentModel
    {
        public string Origin { get; set; } = "";
        public string Destination { get; set; } = "";
        public DateTime EstimatedDelivery { get; set; } = DateTime.UtcNow.AddDays(5);
        public string CustomerEmail { get; set; } = "";
        public string RecipientName { get; set; } = "";
        public string Description { get; set; } = "";
    }
}

@page "/my-shipments"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@attribute [Authorize]
@inject HttpClient Http

<PageTitle>My Shipments</PageTitle>

<h1>My Shipments</h1>

<div class="mb-3">
    <div class="input-group" style="max-width: 500px;">
        <input type="text" class="form-control" placeholder="Enter tracking number..."
               @bind="trackingNumber" @bind:event="oninput"
               @onkeydown="HandleKeyPress" />
        <button class="btn btn-outline-primary" @onclick="TrackShipment">Track</button>
    </div>
</div>

@if (trackedShipment is not null)
{
    <div class="card mb-4 border-primary">
        <div class="card-header bg-primary text-white">
            Tracking Result: @trackedShipment.TrackingNumber
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <p><strong>From:</strong> @trackedShipment.Origin</p>
                    <p><strong>To:</strong> @trackedShipment.Destination</p>
                    <p><strong>Recipient:</strong> @trackedShipment.RecipientName</p>
                </div>
                <div class="col-md-6">
                    <p><strong>Status:</strong>
                        <span class="badge @GetStatusBadgeClass(trackedShipment.Status)">@trackedShipment.Status</span>
                    </p>
                    <p><strong>Estimated Delivery:</strong> @trackedShipment.EstimatedDelivery.ToString("MMMM dd, yyyy")</p>
                    @if (trackedShipment.ActualDelivery.HasValue)
                    {
                        <p><strong>Delivered:</strong> @trackedShipment.ActualDelivery.Value.ToString("MMMM dd, yyyy")</p>
                    }
                </div>
            </div>
            <ShipmentProgressBar Status="trackedShipment.Status" />
        </div>
    </div>
}
else if (trackingError is not null)
{
    <div class="alert alert-warning">@trackingError</div>
}

<h3>Your Shipments</h3>

@if (shipments is null)
{
    <p><em>Loading your shipments...</em></p>
}
else if (!shipments.Any())
{
    <p>You have no shipments yet.</p>
}
else
{
    <div class="row">
        @foreach (var shipment in shipments)
        {
            <div class="col-md-6 col-lg-4 mb-3">
                <div class="card h-100">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <code>@shipment.TrackingNumber</code>
                        <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span>
                    </div>
                    <div class="card-body">
                        <p class="mb-1"><strong>To:</strong> @shipment.Destination</p>
                        <p class="mb-1"><strong>Description:</strong> @shipment.Description</p>
                        <p class="mb-1"><strong>Est. Delivery:</strong> @shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</p>
                        @if (shipment.ActualDelivery.HasValue)
                        {
                            <p class="mb-1 text-success"><strong>Delivered:</strong> @shipment.ActualDelivery.Value.ToString("MMM dd, yyyy")</p>
                        }
                        <ShipmentProgressBar Status="shipment.Status" />
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private List<ShipmentDto>? shipments;
    private ShipmentDto? trackedShipment;
    private string trackingNumber = "";
    private string? trackingError;

    protected override async Task OnInitializedAsync()
    {
        shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("/api/shipments/my");
    }

    private async Task HandleKeyPress(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        trackingError = null;
        trackedShipment = null;

        var response = await Http.GetAsync($"/api/shipments/track/{trackingNumber.Trim()}");
        if (response.IsSuccessStatusCode)
        {
            trackedShipment = await response.Content.ReadFromJsonAsync<ShipmentDto>();
        }
        else
        {
            trackingError = "Shipment not found. Please check the tracking number.";
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Exception => "bg-danger",
        _ => "bg-secondary"
    };
}

@using ShipmentTracker.Client.Models

<div class="mt-2">
    <div class="progress" style="height: 24px;">
        @foreach (var step in steps)
        {
            var isActive = (int)Status >= step.Order;
            var isException = Status == ShipmentStatus.Exception;
            <div class="progress-bar @(isException && step.Order == steps.Length - 1 ? "bg-danger" : isActive ? "bg-success" : "")"
                 role="progressbar"
                 style="width: @(100 / steps.Length)%"
                 aria-valuenow="@(isActive ? 100 : 0)"
                 aria-valuemin="0"
                 aria-valuemax="100">
                @if (isActive || (isException && step.Status == ShipmentStatus.Exception))
                {
                    <small>@step.Label</small>
                }
            </div>
        }
    </div>
</div>

@code {
    [Parameter]
    public ShipmentStatus Status { get; set; }

    private record ProgressStep(int Order, string Label, ShipmentStatus Status);

    private static readonly ProgressStep[] steps =
    [
        new(0, "Pending", ShipmentStatus.Pending),
        new(1, "Picked Up", ShipmentStatus.PickedUp),
        new(2, "In Transit", ShipmentStatus.InTransit),
        new(3, "Out for Delivery", ShipmentStatus.OutForDelivery),
        new(4, "Delivered", ShipmentStatus.Delivered)
    ];
}

