                    <div class="card-body">
                        <p class="mb-1"><strong>To:</strong> @shipment.Destination</p>
                        <p class="mb-1"><strong>Description:</strong> @shipment.Description</p>
                        <p class="mb-1"><strong>Est. Delivery:</strong> @shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</p>
                        @if (shipment.ActualDelivery.HasValue)
                        {
                            <p class="mb-1 text-success"><strong>Delivered:</strong> @shipment.ActualDelivery.Value.ToString("MMM dd, yyyy")</p>
                        }
                        <ShipmentProgressBar Status="shipment.Status" />
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private List<ShipmentDto>? shipments;
    private ShipmentDto? trackedShipment;
    private string trackingNumber = "";
    private string? trackingError;

    protected override async Task OnInitializedAsync()
    {
        shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("/api/shipments/my");
    }

    private async Task HandleKeyPress(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        trackingError = null;
        trackedShipment = null;

        var response = await Http.GetAsync($"/api/shipments/track/{trackingNumber.Trim()}");
        if (response.IsSuccessStatusCode)
        {
            trackedShipment = await response.Content.ReadFromJsonAsync<ShipmentDto>();
        }
        else
        {
            trackingError = "Shipment not found. Please check the tracking number.";
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Exception => "bg-danger",
        _ => "bg-secondary"
    };
}

@using ShipmentTracker.Client.Models

<div class="mt-2">
    <div class="progress" style="height: 24px;">
        @foreach (var step in steps)
        {
            var isActive = (int)Status >= step.Order;
            var isException = Status == ShipmentStatus.Exception;
            <div class="progress-bar @(isException && step.Order == steps.Length - 1 ? "bg-danger" : isActive ? "bg-success" : "")"
                 role="progressbar"
                 style="width: @(100 / steps.Length)%"
                 aria-valuenow="@(isActive ? 100 : 0)"
                 aria-valuemin="0"
                 aria-valuemax="100">
                @if (isActive || (isException && step.Status == ShipmentStatus.Exception))
                {
                    <small>@step.Label</small>
                }
            </div>
        }
    </div>
</div>

@code {
    [Parameter]
    public ShipmentStatus Status { get; set; }

    private record ProgressStep(int Order, string Label, ShipmentStatus Status);

    private static readonly ProgressStep[] steps =
    [
        new(0, "Pending", ShipmentStatus.Pending),
        new(1, "Picked Up", ShipmentStatus.PickedUp),
        new(2, "In Transit", ShipmentStatus.InTransit),
        new(3, "Out for Delivery", ShipmentStatus.OutForDelivery),
        new(4, "Delivered", ShipmentStatus.Delivered)
    ];
}

